insert into prebi_private.cases
(id, title, context, human_feedback, ai_feedback, reveal_note, discussion_prompt, active)
values
('seminar-gespraech', 'Ein Gespräch im Seminar', 'In einem vollständig erfundenen Lehramtsseminar beschreibt eine Studentin eine Gruppenarbeit zum Thema Schulregeln. Während der Diskussion brachte sie mehrere Beispiele ein, zog sich aber zurück, als zwei andere Personen schnell widersprachen. In ihrer Reflexion schreibt sie, dass sie ihre Gedanken lieber erst sortieren wollte. Sie fragt sich, ob sie sich beim nächsten Mal früher einbringen sollte, ohne dabei vorschnell zu reagieren.', array['Du nimmst gut wahr, dass du eigene Gedanken hattest und dich trotzdem zurückgezogen hast. Was genau hat dir in dem Moment geholfen, deine Gedanken zu sortieren?', 'Vielleicht könntest du beim nächsten Gespräch einen Gedanken zunächst als offene Frage einbringen. So bleibt Raum für andere Perspektiven, und du kannst beobachten, ob dir dieser Einstieg Sicherheit gibt.', 'Woran würdest du nach der nächsten Gruppenarbeit erkennen, dass du dich passend eingebracht hast – auch wenn nicht alle deiner Meinung sind?']::text[], array['Du beschreibst eine interessante Spannung: Du hattest eigene Beispiele, hast dich nach dem Widerspruch aber zurückgenommen. Deine Beobachtung macht nachvollziehbar, warum du zunächst sortieren wolltest.', 'Für ein nächstes Gespräch könntest du dir vornehmen, ein Beispiel früh als Frage einzubringen. Das könnte dir ermöglichen, deine Idee zu teilen und zugleich offen für andere Sichtweisen zu bleiben.', 'Überlege anschließend, wie sich dieser Versuch für dich angefühlt hat und was du daraus für weitere Gruppengespräche mitnehmen möchtest.']::text[], 'Beide Rückmeldungen greifen dieselbe Situation auf. Die eine fragt genauer nach dem Erleben im Moment, die andere formuliert einen möglichen nächsten Versuch.', 'Welche Rückmeldung hilft dir eher dabei, die Situation weiter zu verstehen – und welche eher dabei, einen nächsten Schritt zu planen?', true),
('stundenbeginn', 'Der Einstieg in die Stunde', 'In diesem fiktiven Praxisbeispiel plant ein Student einen Einstieg für eine sechste Klasse. Er möchte, dass die Kinder zuerst eigene Vermutungen sammeln. Als die Klasse am Morgen unruhiger ist als erwartet, erklärt er seine Aufgabe mehrfach und übernimmt schließlich die Gesprächsführung. In seiner Reflexion fragt er, ob eine kürzere Erklärung oder ein anderer Start der Klasse mehr Eigenständigkeit ermöglicht hätte.', array['Du beschreibst, wie die Unruhe deine Planung beeinflusst hat. Welche Signale der Klasse haben dich dazu gebracht, die Gesprächsführung zu übernehmen?', 'Ein klar sichtbarer erster Arbeitsschritt könnte den Einstieg entlasten. Du könntest zum Beispiel eine Vermutung als Beispiel notieren und danach eine kurze Denkzeit geben.', 'Welche Hinweise würden dir zeigen, dass die Kinder die Aufgabe verstanden haben, ohne dass du den Austausch selbst tragen musst?']::text[], array['Deine Reflexion macht deutlich, dass du auf die Unruhe der Klasse reagiert hast, indem du mehr erklärt und die Führung übernommen hast. Das kann in einer unerwarteten Situation zunächst Orientierung geben.', 'Beim nächsten Mal könntest du die Aufgabe in einem Satz formulieren und den ersten Schritt sichtbar machen. Eine kurze individuelle Denkzeit könnte den Kindern helfen, eigene Vermutungen zu entwickeln.', 'Beobachte, ob sich dadurch mehr Kinder am Austausch beteiligen und wie du mit verbleibender Unruhe umgehst.']::text[], 'Die Antworten unterscheiden sich darin, wie stark sie nach den beobachteten Signalen fragen und wie konkret sie einen nächsten Unterrichtsversuch skizzieren.', 'Wie konkret sollte Feedback einen nächsten Schritt vorschlagen, ohne die eigene Analyse der Situation vorwegzunehmen?', true),
('arbeitsauftrag', 'Ein offener Arbeitsauftrag', 'Eine fiktive Studentin erprobt in einer fünften Klasse einen offenen Arbeitsauftrag zu unterschiedlichen Lösungswegen. Einige Kinder beginnen sofort, andere fragen nach einem konkreten Beispiel. Die Studentin ergänzt daraufhin mehrere Hinweise an der Tafel. Später merkt sie, dass manche Kinder nun denselben Weg nutzen. In ihrer Reflexion möchte sie herausfinden, wie sie Orientierung geben kann, ohne die Offenheit der Aufgabe einzuschränken.', array['Du beschreibst zwei wichtige Beobachtungen: Die Kinder brauchten unterschiedlich viel Orientierung, und die zusätzlichen Hinweise haben ihre Lösungswege beeinflusst. Welche Reaktion hat dich dabei besonders überrascht?', 'Du könntest beim nächsten Mal ein Beispiel zeigen, das nur einen Teil der Aufgabe sichtbar macht, und anschließend verschiedene Wege sammeln lassen.', 'Woran könntest du erkennen, ob deine Unterstützung Orientierung gibt, aber noch eigene Entscheidungen offenlässt?']::text[], array['In deiner Beschreibung wird sichtbar, dass ein offener Auftrag unterschiedliche Bedürfnisse auslöst. Deine zusätzlichen Hinweise haben offenbar Sicherheit gegeben, zugleich aber die Vielfalt der Lösungswege verändert.', 'Eine Möglichkeit wäre, zunächst nur einen kleinen Einstiegshinweis zu geben und die Kinder danach eigene Wege ausprobieren zu lassen. Unterschiedliche Lösungen könntest du später gemeinsam vergleichen.', 'Achte darauf, welche Kinder mit dieser Unterstützung starten und ob verschiedene Vorgehensweisen weiterhin sichtbar werden.']::text[], 'Beide Antworten beziehen sich auf Orientierung und Eigenständigkeit. Sie setzen unterschiedliche Akzente bei der gemeinsamen Analyse und bei einer möglichen Unterrichtsvariation.', 'Welche Art von Frage würde dir helfen, die Wirkung deiner Unterstützung genauer einzuschätzen?', true)
